{"code": "def authorize(request: dict, policies: list[dict]) -> str:
    """
    Decide access requests against the policy set.

    Returns "ALLOW" or "DENY" based on XACML 3.0 Appendix C.2 deny-overrides rule.
    """

    # Validation phase
    # Validate request
    required_request_fields = {'subject', 'roles', 'action', 'resource'}
    for field in required_request_fields:
        if field not in request:
            raise ValueError(f"Request missing required field: {field}")

    if not isinstance(request['roles'], list):
        raise ValueError("Request 'roles' must be a list")

    # Validate policies
    for policy in policies:
        required_policy_fields = {'effect', 'principal', 'action', 'resource'}
        for field in required_policy_fields:
            if field not in policy:
                raise ValueError(f"Policy missing required field: {field}")

        effect = policy['effect']
        if effect not in ('ALLOW', 'DENY'):
            raise ValueError(f"Invalid effect: {effect}")

    # Helper functions for pattern matching
    def principal_matches(principal, request_subject, request_roles):
        """Check if a principal matches the request."""
        if principal == '*':
            return True
        if principal.startswith('user:'):
            return principal == f"user:{request_subject}"
        if principal.startswith('role:'):
            role_name = principal[5:]  # Remove "role:" prefix
            return role_name in request_roles
        return False

    def pattern_matches(pattern, value):
        """Check if a pattern matches a value (with trailing * as prefix)."""
        if pattern == '*':
            return True
        if pattern.endswith('*') and len(pattern) > 1:
            prefix = pattern[:-1]
            return value.startswith(prefix)
        return pattern == value

    # Decision phase - XACML 3.0 Appendix C.2 deny-overrides
    has_allow = False
    for policy in policies:
        # Check if all policy conditions match
        if not principal_matches(policy['principal'], request['subject'], request['roles']):
            continue
        if not pattern_matches(policy['action'], request['action']):
            continue
        if not pattern_matches(policy['resource'], request['resource']):
            continue

        # Policy matches
        if policy['effect'] == 'DENY':
            return 'DENY'
        elif policy['effect'] == 'ALLOW':
            has_allow = True

    # Return ALLOW if found any matching ALLOW, otherwise DENY
    return 'ALLOW' if has_allow else 'DENY'
